input.command:
awk '
BEGIN { print "row_id,account_id,event_time,amount_usd,is_weekend,amount_7d" }
function val(line,  s) { s=line; sub(/^[^:]*:[ \t]*/,"",s); gsub(/[",]/,"",s); gsub(/[ \t]+$/,"",s); return s }
/"row_id":/     { r=val($0) }
/"account_id":/ { a=val($0) }
/"event_time":/ { e=val($0) }
/"amount_usd":/ { u=val($0) }
/"is_weekend":/ { w=val($0) }
/"amount_7d":/  { d=val($0); print r","a","e","u","w","d }
' .tmp/derived.json > .tmp/derived.csv
wc -l .tmp/derived.csv; echo "---"; head -4 .tmp/derived.csv; echo "---"; tail -2 .tmp/derived.csv
